#[derive(Debug,Clone,serde::Serialize)]pub struct AutomationPlan{pub steps:Vec<String>,pub max_steps:u32,pub requires_confirmation:bool}
pub fn plan(input:&str)->Result<AutomationPlan,String>{let q=input.trim();if q.is_empty(){return Err("Task is empty".into())}let sensitive=["delete","remove","password","payment","bank","shutdown","restart","install","uninstall","powershell","shell","رسالة","حذف","كلمة المرور","دفع","بنك","إيقاف"];let low=q.to_lowercase();let sensitive_hit=sensitive.iter().any(|x|low.contains(x));Ok(AutomationPlan{steps:vec!["observe_ui_tree".into(),"observe_screen_if_needed".into(),"permission_check".into(),"execute_one_tool".into(),"verify_result".into()],max_steps:25,requires_confirmation:sensitive_hit})}